const express = require('express');
const puppeteer = require('puppeteer');
const { Pool } = require('pg');

const app = express();
app.use(express.json());
const db = new Pool({ connectionString: process.env.DATABASE_URL });

app.post('/api/reports/export-pdf', async (req, res) => {
  const { reportId } = req.body;
  if (!reportId) {
    return res.status(400).json({ error: 'Missing reportId' });
  }

  // Ensure report belongs to the authenticated user's tenant
  const result = await db.query(
    'SELECT id, tenant_id, file_slug FROM generated_reports WHERE id = $1 AND tenant_id = $2',
    [reportId, req.user.tenant_id]
  );
  if (result.rows.length === 0) {
    return res.status(404).json({ error: 'Report not found' });
  }

  const report = result.rows[0];
  const targetUrl = `http://internal-reporting.local/render/${report.file_slug}`;

  const browser = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox'] });
  try {
    const page = await browser.newPage();
    await page.setExtraHTTPHeaders({ 'X-Internal-Service-Key': process.env.INTERNAL_SERVICE_KEY });
    await page.goto(targetUrl, { waitUntil: 'networkidle0' });
    const pdfBuffer = await page.pdf({ format: 'A4', printBackground: true });

    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `attachment; filename="report_${report.id}.pdf"`);
    return res.send(pdfBuffer);
  } catch (err) {
    return res.status(500).json({ error: 'PDF generation failed' });
  } finally {
    await browser.close();
  }
});

module.exports = app;
